    def _restock_retailers(self, day: int) -> None:
        target = self.restock_lot_size
        for r in self.retailers:
            r.adjust_prices()
        if day % self.restock_interval_days == 0:
            remaining_capacity = self.supply_capacity_per_day
            for r in self.retailers:
                if remaining_capacity <= 0:
                    break
