    def _purchase_if_needed(self, person: Person) -> bool:
        if person.masks_inventory > 0:
            return False
        stocked = [r for r in self.retailers if r.inventory_level > 0]
        if not stocked:
            return True
        r = self.rng.choice(stocked)
        purchased, shortage = r.sell_masks(1)
        person.masks_inventory += purchased
        if purchased > 0 and self.subsidy_amount > 0:
            self.public_cost_subsidies += self.subsidy_amount * purchased
        return shortage

