    def _pre_sample_visits(self) -> Dict[str, List[Person]]:
        visitors_by_type: Dict[str, List[Person]] = {t: [] for t in self.locations_by_type.keys()}
        for person in self.people.values():
            for t, prob in person.daily_mobility_profile.items():
                if t != 'home' and prob > 0.0 and t in visitors_by_type and self.rng.random() < prob:
                    visitors_by_type[t].append(person)
        return visitors_by_type

